## Why This Is Asked
Tests ability to generalize DP with an extra resource dimension and reconstruction, a common pattern in grid path problems with constraints. It also probes edge-case handling when i or j is at 0 and when t=0. 

## Key Concepts
- DP with an extra dimension for resource usage (K diagonals)
- 3-way transitions and path reconstruction
- Time/space trade-offs and potential optimizations

## Code Example
```javascript
function minCostPath(grid, K) {
  const n = grid.length, m = grid[0].length;
  const INF = 1e15;
  const dp = Array.from({ length: n }, () => Array.from({ length: m }, () => Array(K+1).fill(INF)));
  const parent = Array.from({ length: n }, () => Array.from({ length: m }, () => Array(K+1).fill(null)));
  dp[0][0][0] = grid[0][0];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      for (let t = 0; t <= K; t++) {
        if (i === 0 && j === 0 && t === 0) continue;
        let best = INF, pick = null;
        if (i > 0 && dp[i-1][j][t] < best) { best = dp[i-1][j][t]; pick = [i-1, j, t]; }
        if (j > 0 && dp[i][j-1][t] < best) { best = dp[i][j-1][t]; pick = [i, j-1, t]; }
        if (i > 0 && j > 0 && t > 0 && dp[i-1][j-1][t-1] < best) { best = dp[i-1][j-1][t-1]; pick = [i-1, j-1, t-1]; }
        if (best < INF) {
          dp[i][j][t] = best + grid[i][j];
          if (pick) parent[i][j][t] = pick;
        }
      }
    }
  }
  // find best end state
  let bestCost = INF, endT = 0;
  for (let t = 0; t <= K; t++) {
    if (dp[n-1][m-1][t] < bestCost) { bestCost = dp[n-1][m-1][t]; endT = t; }
  }
  // reconstruct path
  const path = [];
  let i = n-1, j = m-1, t = endT;
  while (i !== 0 || j !== 0 || t !== 0) {
    path.push([i, j]);
    const p = parent[i][j][t];
    if (!p) break;
    [i, j, t] = p;
  }
  path.push([0,0]);
  path.reverse();
  return { cost: bestCost, path };
}
```

## Follow-up Questions
- How to reduce space to O(m K) using rolling arrays?
- How would you handle negative costs or unreachable endpoints?

## Why This Is Asked
Tests interval DP with exactly k block selection, reconstruction, and non-adjacent constraint handling. Requires precomputing interval values (max-min) and a clean end-at-i transition that accounts for the gap requirement.

## Key Concepts
- Interval DP with exactly k non-adjacent blocks
- Precomputation of val(l,r) = max(A[l..r]) - min(A[l..r]) using O(n²) sliding window enumeration
- Reconstruction pointers to retrieve endpoints
- Time complexity: O(n²) precomputation + O(kn²) DP; Space: O(n²) for val table + O(n·k) for DP
- Edge cases: k > ⌊n/2⌋ (impossible, return error), empty arrays (return 0)

## Code Example
```javascript
function maxKSumIntervals(A, k) {
  const n = A.length;
  const val = Array.from({ length: n }, () => Array(n).fill(0));

  for (let l = 0; l < n; l++) {
    let min = A[l], max = A[l];
    for (let r = l; r < n; r++) {
      min = Math.min(min, A[r]);
      max = Math.max(max, A[r]);
      val[l][r] = max - min;
    }
  }

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const parent = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));

  for (let i = 0; i <= n; i++) dp[i][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      dp[i][t] = dp[i-1][t];
      parent[i][t] = { skip: true };

      for (let j = 1; j <= i; j++) {
        const prev = j >= 2 ? dp[j-2][t-1] : (t === 1 ? 0 : -Infinity);
        if (prev === -Infinity) continue;
        const curr = prev + val[j-1][i-1];
        if (curr > dp[i][t]) {
          dp[i][t] = curr;
          parent[i][t] = { start: j, end: i, prev: j - 2 };
        }
      }
    }
  }

  const intervals = [];
  let i = n, t = k;
  while (t > 0 && parent[i][t]) {
    const p = parent[i][t];
    if (!p.skip) {
      intervals.push([p.start, p.end]);
      i = p.prev;
      t--;
    } else {
      i--;
    }
  }

  return { maxValue: dp[n][k], intervals: intervals.reverse() };
}
```

## Why This Is Asked
Tests DP partitioning with a non-sum objective and reconstruction requirements.

## Key Concepts
- DP over partitions with dp[i][t]
- Precomputing max-min for all subarrays
- Path reconstruction via parent pointers

## Code Example
```javascript
function maxMinSubarrayVal(arr){
  const n = arr.length;
  const maxVal = Array.from({length:n}, ()=>Array(n).fill(0));
  const minVal = Array.from({length:n}, ()=>Array(n).fill(0));
  for(let i=0;i<n;i++){
    let curMax = arr[i], curMin = arr[i];
    for(let j=i;j<n;j++){
      curMax = Math.max(curMax, arr[j]);
      curMin = Math.min(curMin, arr[j]);
      maxVal[i][j] = curMax;
      minVal[i][j] = curMin;
    }
  }
  const val = (l,r)=> maxVal[l][r] - minVal[l][r];
  return val;
}

function bestPartition(arr, k){
  const n = arr.length;
  const val = maxMinSubarrayVal(arr);
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const parent = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for(let i=1;i<=n;i++) dp[i][1] = val(0,i-1);
  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<=i-1;j++){
        const cand = dp[j][t-1] + val(j, i-1);
        if(cand > dp[i][t]){ dp[i][t] = cand; parent[i][t]=j; }
      }
    }
  }
  // reconstruct
  let blocks = [];
  let i=n, t=k;
  while(t>0){
    const j = parent[i][t];
    blocks.push([j, i-1]);
    i = j; t--;
  }
  blocks.reverse();
  return {value: dp[n][k], blocks};
}
```

## Follow-up Questions
- How to optimize memory to O(nk)?
- Can you handle ties deterministically for block reconstruction?

## Why This Is Asked

Tests the ability to model non-crossing, higher-arity structures with DP and reconstruct a solution.

## Key Concepts

- DP state dp[i][t] for i and t
- Non-crossing triple formation
- Reconstruction via backpointers
- Time/space trade-offs and optimization path

## Code Example

```javascript
function maxTriples(A, n, k) {
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-Infinity));
  const prv = Array.from({length: n+1}, () => Array(k+1).fill(null));
  dp[0][0] = 0;
  for (let i=1; i<=n; i++) {
    for (let t=0; t<=k; t++) {
      dp[i][t] = dp[i-1][t];
      if (t>0) {
        for (let i1=1; i1<i; i1++) {
          for (let j=i1+1; j<i; j++) {
            const prev = (i1>=2 ? dp[i1-1][t-1] : (t-1===0 ? 0 : -Infinity));
            const val = prev + A[i1-1]*A[j-1]*A[i-1];
            if (val > dp[i][t]) { dp[i][t] = val; prv[i][t] = {i1, j}; }
          }
        }
      }
    }
  }
  // reconstruction logic would backtrack using prv
  return {value: dp[n][k], triples: []};
}
```

## Why This Is Asked

Tests a non-trivial DP over a linear sequence with a non-crossing constraint and reconstruction of the chosen pairs. It balances readability with the need to optimize across many left endpoints efficiently.

## Key Concepts

- Non-crossing pairings on a line
- DP by right endpoint with reconstruction
- Time/space trade-offs; potential 1D optimization for i dimension

## Code Example

```javascript
function maxNonCrossingPairs(A, k){
  const n = A.length;
  const NEG = -1e15;
  const dp = Array.from({length: n}, () => Array(k+1).fill(NEG));
  const take = Array.from({length: n}, () => Array(k+1).fill(-1));
  for(let i=0;i<n;i++) dp[i][0] = 0;
  for(let i=0;i<n;i++){
    for(let t=1;t<=k;t++){
      let best = i>0 ? dp[i-1][t] : 0;
      let bestJ = -1;
      for(let j=0;j<i;j++){
        const left = (j>=1) ? dp[j-1][t-1] : (t-1===0 ? 0 : NEG);
        const val = left + Math.abs(A[i]-A[j]);
        if(val > best){ best = val; bestJ = j; }
      }
      dp[i][t] = best;
      take[i][t] = bestJ;
    }
  }
  // reconstruction sketch (omitted for brevity)
  return { value: dp[n-1][k], pairs: [] };
}
``` 

## Follow-up Questions

- How would you enforce exactly k pairs instead of at most k?
- Can you optimize memory to O(n) or derive a monotone queue optimization for certain A distributions?

## Why This Is Asked
This problem tests understanding of partition dynamic programming with bitwise operations, commonly encountered in optimization scenarios for data processing and segmentation tasks.

## Key Concepts
- Partition DP formulation
- Subarray OR precomputation
- Boundary reconstruction
- Time/space complexity analysis

## Code Example
```javascript
function maxOrPartition(A, k) {
  const n = A.length;
  const OR = Array.from({length: n+1}, () => Array(n+1).fill(0));

  // Precompute OR for all subarrays
  for (let i = 0; i < n; i++) {
    let cur = 0;
    for (let j = i; j < n; j++) {
      cur |= A[j];
      OR[i][j+1] = cur;
    }
  }

  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-Infinity));
  const par = Array.from({length: n+1}, () => Array(k+1).fill(-1));

  dp[0][0] = 0;

  for (let t = 1; t <= k; t++) {
    for (let i = 1; i <= n; i++) {
      for (let j = 0; j < i; j++) {
        if (dp[j][t-1] !== -Infinity) {
          const val = dp[j][t-1] + OR[j][i];
          if (val > dp[i][t]) {
            dp[i][t] = val;
            par[i][t] = j;
          }
        }
      }
    }
  }

  // Reconstruct blocks
  const blocks = [];
  let curr = n;
  for (let t = k; t >= 1; t--) {
    const start = par[curr][t];
    blocks.unshift([start, curr-1]);
    curr = start;
  }

  return { maxSum: dp[n][k], blocks };
}
```

## Complexity
Time: O(n²k) due to triple nested loops, Space: O(nk + n²) for DP tables and OR precomputation.

## Why This Is Asked
Tests DP state augmentation for a path with a constrained number of turns, combining path optimization with reconstruction. It demands careful handling of transitions when direction changes. 

## Key Concepts
- DP on grid paths with turn constraints
- 4D state dp[i][j][t][dir]
- Reconstruction via parent pointers
- Time: O(n*m*k); Space: O(n*m*k)

## Code Example
```javascript
function maxPathWithKTurns(grid, K) {
  const n = grid.length, m = grid[0].length;
  const NEG = -1e15;
  const dp = Array.from({length: n}, () =>
    Array.from({length: m}, () => Array.from({length: K+1}, () => [NEG, NEG]))
  );
  dp[0][0][0][0] = grid[0][0];
  dp[0][0][0][1] = grid[0][0];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      if (i === 0 && j === 0) continue;
      for (let t = 0; t <= K; t++) {
        const val = grid[i][j];
        if (j > 0) {
          dp[i][j][t][0] = Math.max(dp[i][j][t][0], dp[i][j-1][t][0] + val);
          if (t > 0) dp[i][j][t][0] = Math.max(dp[i][j][t][0], dp[i][j-1][t-1][1] + val);
        }
        if (i > 0) {
          dp[i][j][t][1] = Math.max(dp[i][j][t][1], dp[i-1][j][t][1] + val);
          if (t > 0) dp[i][j][t][1] = Math.max(dp[i][j][t][1], dp[i-1][j][t-1][0] + val);
        }
      }
    }
  }
  // reconstruction would backtrack using stored choices (omitted for brevity)
  return {dp, best: Math.max(...Array.from({length:K+1}, (_,t)=>Math.max(dp[n-1][m-1][t][0], dp[n-1][m-1][t][1])))};
}
```

## Why This Is Asked
Assesses ability to turn path-based objectives into simple local transitions without extraneous state. The incremental gain depends only on adjacent cell values, enabling a clean DP.

## Key Concepts
- Grid DP with monotone moves
- Backpointers for path reconstruction
- Space optimization potential

## Code Example
```javascript
function maxAscents(grid){
  const n=grid.length, m=grid[0].length;
  const dp=Array.from({length:n}, ()=>Array(m).fill(0));
  const par=Array.from({length:n}, ()=>Array(m).fill(null));
  for(let i=0;i<n;i++){
    for(let j=0;j<m;j++){
      if(i===0 && j===0) continue;
      let top=-Infinity, left=-Infinity;
      if(i>0) top = dp[i-1][j] + (grid[i-1][j] < grid[i][j] ? 1:0);
      if(j>0) left = dp[i][j-1] + (grid[i][j-1] < grid[i][j] ? 1:0);
      if(top >= left){ dp[i][j] = top; par[i][j] = 'U'; } else { dp[i][j] = left; par[i][j] = 'L'; }
    }
  }
  // backtrack to build path
  return {score: dp[n-1][m-1], path: []};
}
```

## Why This Is Asked
Tests DP setup for segment selection with non-adjacency and reconstruction, a common beginner DP pattern with a twist.

## Key Concepts
- DP over index i and blocks t
- Enforce non-adjacency via s-2 reference
- Prefix sums for O(1) subarray sums
- Reconstruction pointers for endpoints
- Time/space trade-offs; possible optimization to O(nk) time and O(n) space per k

## Code Example
```javascript
function maxKSubarraysSum(A, k) {
  const n = A.length;
  const P = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) P[i + 1] = P[i] + A[i];

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const take = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      // skip i
      dp[i][t] = Math.max(dp[i][t], dp[i - 1][t]);
      if (t > 0) {
        for (let s = 1; s <= i; s++) {
          const sum = P[i] - P[s - 1];
          const prev = (s >= 2) ? dp[s - 2][t - 1] : (t - 1 === 0 ? 0 : -Infinity);
          const cand = sum + prev;
          if (cand > dp[i][t]) {
            dp[i][t] = cand;
            take[i][t] = s;
          }
        }
      }
    }
  }
  // reconstruction would trace back using 'take' from (n, bestT)
  return { maxSum: dp[n][0], blocks: [] };
}
```

## Why This Is Asked

Tests a constrained subsequence DP with gap bounds and reconstruction, a common real-world scheduling/selection pattern.

## Key Concepts

- DP on sequences with restricted gaps
- State dp[i][t] and transition over a window [i-U, i-L]
- Path reconstruction with parent pointers

## Code Example

```javascript
function maxSumWithGaps(A, k, L, U){
  const n = A.length, NEG = -1e15;
  const dp = Array.from({length: k+1}, ()=> Array(n).fill(NEG));
  const par = Array.from({length: k+1}, ()=> Array(n).fill(-1));
  for(let i=0;i<n;i++) dp[1][i] = A[i];
  for(let t=2;t<=k;t++){
    for(let i=0;i<n;i++){
      let best = NEG, bestj = -1;
      for(let j=i-U;j<=i-L;j++){
        if(j>=0 && dp[t-1][j] > best){ best = dp[t-1][j]; bestj = j; }
      }
      if(bestj!=-1){ dp[t][i] = A[i] + best; par[t][i] = bestj; }
    }
  }
  let end = -1, best = NEG;
  for(let i=0;i<n;i++) if(dp[k][i] > best){ best = dp[k][i]; end = i; }
  const indices = [];
  let cur = end;
  for(let t=k; t>=1; t--){ indices.push(cur); cur = par[t][cur]; }
  indices.reverse();
  return {best, indices};
}
```

## Why This Is Asked

This question tests dynamic programming skills for selecting exactly k disjoint subarrays with a per-subarray penalty—a common variant in coding interviews that extends standard maximum subarray problems.

## Key Concepts

- **Non-overlapping constraint**: Subarrays must not intersect, handled by the state machine.
- **Dual-state DP**: Maintaining both global (dp) and local (end) states to track ongoing vs. completed selections.
- **Reconstruction**: Tracing back decisions to recover actual subarray endpoints.
- **Optimization**: Balancing time complexity (O(nk)) against space (full vs. rolling arrays).

## Code Example

```javascript
const solve = (A, k, c) => {
  const n = A.length;
  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const end = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const choice = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));

  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      // Not taking a subarray ending at i
      if (dp[i-1][t] >= end[i][t]) {
        dp[i][t] = dp[i-1][t];
        choice[i][t] = 'skip';
      } else {
        dp[i][t] = end[i][t];
        choice[i][t] = 'end';
      }

      // Taking/starting subarray at i
      if (t > 0) {
        const startNew = dp[i-1][t-1] + A[i-1] - c;
        const extend = end[i-1][t] + A[i-1] - c;
        end[i][t] = Math.max(extend, startNew);
      }
    }
  }

  // Reconstruction logic would go here
  return { value: dp[n][k], subarrays: [] };
};
```

## Complexity

- **Time:** O(nk)
- **Space:** O(nk) for full DP, O(k) for optimized version

## Why This Is Asked

Tests a fresh DP angle: interval-based value depends on distinct characters within each substring, plus precise reconstruction for k blocks.

## Key Concepts

- Non-overlapping interval DP
- Precomputing distinct counts for all substrings
- Reconstruction via back-pointers
- Time/space trade-offs and potential optimizations

## Code Example

```javascript
// Implementation sketch
function maxKSubstrings(s, k) {
  const n = s.length;
  const dist = Array.from({length: n}, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    const freq = new Array(26).fill(0);
    let setBits = 0;
    for (let j = i; j >= 0; j--) {
      const idx = s.charCodeAt(j) - 97;
      if (freq[idx]++ === 0) setBits++;
      dist[j][i] = setBits;
    }
  }

  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-Infinity));
  const prev = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  const start = Array.from({length: n+1}, () => Array(k+1).fill(-1));

  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    dp[i][0] = 0;
    for (let t = 1; t <= k; t++) {
      // Option 1: skip i
      if (dp[i-1][t] > dp[i][t]) {
        dp[i][t] = dp[i-1][t];
        prev[i][t] = i-1;
        start[i][t] = start[i-1][t];
      }

      // Option 2: end t-th substring at i
      for (let s = 1; s <= i; s++) {
        const val = dp[s-1][t-1] + dist[s-1][i-1];
        if (val > dp[i][t]) {
          dp[i][t] = val;
          prev[i][t] = s-1;
          start[i][t] = s-1;
        }
      }
    }
  }

  // Reconstruct substrings
  const result = [];
  let i = n, t = k;
  while (t > 0 && i > 0) {
    if (prev[i][t] === i-1) {
      i--;
    } else {
      result.unshift([start[i][t]+1, i]);
      i = prev[i][t];
      t--;
    }
  }

  return { maxValue: dp[n][k], substrings: result };
}
```

Time complexity: O(n²k) for DP transitions + O(n²) for preprocessing. Space: O(n² + nk). Optimizations include limiting the inner loop or using convex hull tricks for special cases.

## Why This Is Asked
Tests ability to design a DP with a non-trivial cost function and prefix optimization.

## Key Concepts
- DP on prefixes and partitions
- O(1) substring cost via precomputed diff/pref
- Path reconstruction via parent pointers

## Code Example
```javascript
// Precompute diff and prefix
let diff = Array(n+1).fill(0);
for (let i=2;i<=n;i++) diff[i] = s[i-1] !== s[i-2] ? 1:0;
let pref = Array(n+1).fill(0);
for (let i=2;i<=n;i++) pref[i] = pref[i-1] + diff[i];

// cost(a,b)
function cost(a,b){ return pref[b] - pref[a]; }

// DP
let dp = Array.from({length:n+1}, ()=> Array(k+1).fill(Infinity));
let par = Array.from({length:n+1}, ()=> Array(k+1).fill(-1));
for(let i=1;i<=n;i++){ dp[i][1] = cost(1,i); }

for(let t=2;t<=k;t++){
  for(let i=t;i<=n;i++){
    for(let p=t-1;p<=i-1;p++){
      let val = dp[p][t-1] + cost(p+1,i);
      if(val < dp[i][t]){ dp[i][t] = val; par[i][t] = p; }
    }
  }
}
```

